from pint import UnitRegistryureg = UnitRegistry()def to_unit(value, from_u: str, to_u: str):    """    Convert a numeric value from one unit to another using pint.    Returns the converted magnitude.    """    if value is None or from_u is None or to_u is None:        return value    try:        return (value * ureg(from_u)).to(to_u).magnitude    except Exception:        return None